5	import { logger } from './utils/logger';
6	import { authMiddleware } from './middleware/auth';
7	import { errorHandler, notFoundHandler } from './middleware/errorHandler';
8	import { startKeepAlive } from './utils/keepalive';
9	
10	// APIエンドポイント
11	import { syncRoles } from './api/rolesSync';
12	import { syncAllRoles } from './api/rolesSyncAll';
13	import { getNickname, updateNickname } from './api/nickname';
14	import { createGeneration } from './api/generation';
15	import { getMemberStatus } from './api/memberStatus';
16	import { getAllMembers } from './api/members';
17	import { assignRole, removeRole, listDiscordRoles } from './api/roles';
18	
19	const app = express();
20	const PORT = process.env.PORT || 3000;
21	
22	// CORS設定
23	const corsOptions = {
24	  origin: process.env.ALLOWED_ORIGINS 
25	    ? process.env.ALLOWED_ORIGINS.split(',')
26	    : '*', // 本番環境では具体的なオリジンを指定することを推奨
27	  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
28	  allowedHeaders: ['Content-Type', 'Authorization'],
29	  credentials: true,
30	  maxAge: 86400, // プリフライトリクエストのキャッシュ時間（24時間）
31	};
32	
33	// ミドルウェア
34	app.use(cors(corsOptions));
35	app.use(express.json());
36	
37	// ヘルスチェック（認証不要）
38	app.get('/health', async (req, res) => {
39	  try {
40	    const client = getDiscordClient();
41	    const wsStatus = client.ws.status;
42	    const guildId = getGuildId();
43	    let guildOk = false;
44	    let guildError = '';
45	    try {
46	      const guild = await client.guilds.fetch(guildId);
47	      guildOk = !!guild;
48	    } catch (e: any) {
49	      guildError = e.message || 'Unknown error';
50	    }
51	    res.json({
52	      status: guildOk ? 'ok' : 'degraded',
53	      timestamp: new Date().toISOString(),
54	      discord: {
55	        ws_status: wsStatus,
56	        bot_user: client.user?.tag || null,
57	        guild_id: guildId,
58	        guild_accessible: guildOk,
59	        guild_error: guildError || undefined,
60	      },
61	    });
62	  } catch (e) {
63	    res.json({ status: 'ok', timestamp: new Date().toISOString(), discord: { error: 'Client not initialized' } });
64	  }
65	});
66	
67	// 認証が必要なエンドポイント
68	app.post('/api/roles/sync', authMiddleware, syncRoles);
69	app.post('/api/roles/sync-all', authMiddleware, syncAllRoles);
70	app.post('/api/roles/assign', authMiddleware, assignRole);
71	app.post('/api/roles/remove', authMiddleware, removeRole);
72	app.get('/api/roles/discord-list', authMiddleware, listDiscordRoles);
73	app.get('/api/nickname', authMiddleware, getNickname);
74	app.post('/api/nickname/update', authMiddleware, updateNickname);
75	app.post('/api/generation', authMiddleware, createGeneration);
76	app.get('/api/member/status', authMiddleware, getMemberStatus);
77	app.get('/api/members', authMiddleware, getAllMembers);
78	
79	// 404ハンドラー
80	app.use(notFoundHandler);
81	
82	// エラーハンドラー
83	app.use(errorHandler);
84	
