91	      throw new Error('DISCORD_TOKEN is not set in environment variables');
92	    }
93	
94	    logger.info('Logging in Discord Bot...');
95	    await loginDiscordBot(discordToken);
96	
97	    // Supabaseキープアライブを開始
98	    startKeepAlive();
